const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define southern Iran region (approximate area)
  const southernIran = ee.Geometry.Polygon([
    [[50.0, 27.0], [60.0, 27.0], [60.0, 30.0], [50.0, 30.0], [50.0, 27.0]]
  ]);

  // Date definitions
  const date1 = '2020-01-08';
  const date2 = '2020-01-13';

  // Function to get water extent for a specific date
  function getWaterExtent(date) {
    const startDate = ee.Date(date);
    const endDate = startDate.advance(1, 'day');

    // Try Sentinel-2
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(southernIran)
      .filterDate(startDate, endDate);

    const size = collection.size().getInfo();
    console.log(`${date} - Sentinel-2 images found: ${size}`);

    if (size === 0) {
      return null;
    }

    // Use mosaic to combine images if multiple
    const image = collection.mosaic();

    // Cloud masking using QA60
    const cloudMask = image.select('QA60').bitwiseAnd(1 << 10).eq(0)
      .and(image.select('QA60').bitwiseAnd(1 << 11).eq(0));

    const masked = image.updateMask(cloudMask);

    // Calculate NDWI (Green - NIR) / (Green + NIR)
    const ndwi = masked.normalizedDifference(['B3', 'B8']).rename('NDWI');

    // Threshold for water (NDWI > 0)
    const water = ndwi.gt(0);

    // Count water pixels
    const stats = water.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: southernIran,
      scale: 3000,
      maxPixels: 1e9
    });

    const waterPixels = stats.get('NDWI').getInfo();

    // Also count total valid pixels
    const validStats = water.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: southernIran,
      scale: 3000,
      maxPixels: 1e9
    });

    const totalPixels = validStats.get('NDWI').getInfo();

    return { waterPixels: waterPixels, totalPixels: totalPixels };
  }

  // Get water extent for both dates
  const result1 = getWaterExtent(date1);
  const result2 = getWaterExtent(date2);

  // Check for missing data
  if (result1 === null || result2 === null) {
    console.log("Missing data for one or both dates.");
    console.log("<answer>C1</answer>");
    return;
  }

  console.log(`Jan 8, 2020 - Water pixels: ${result1.waterPixels}, Total valid: ${result1.totalPixels}`);
  console.log(`Jan 13, 2020 - Water pixels: ${result2.waterPixels}, Total valid: ${result2.totalPixels}`);

  // Check for no valid pixels
  if (result1.totalPixels === 0 || result2.totalPixels === 0) {
    console.log("No valid pixels after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for invalid results
  if (result1.waterPixels === null || result2.waterPixels === null ||
      isNaN(result1.waterPixels) || isNaN(result2.waterPixels)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare water extent
  if (result2.waterPixels > result1.waterPixels) {
    console.log("Water extent increased on Jan 13 compared to Jan 8.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Water extent did not increase on Jan 13 compared to Jan 8.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
